// IL DIZIONARIO ITALIANO dei giochi di parole (Paroliere, Anagrammi a squadre): 334005 parole (più le circa 37.000 di paroliere-aggiunte.js), comprese le forme
// flesse (plurali, femminili, tutte le voci dei verbi), senza accenti, da 3 a 16 lettere. Niente nomi propri, sigle,
// interiezioni, parolacce e troncamenti poetici.
// Fonte delle parole: Morph-it! di Marco Baroni ed Eros Zanchetta (licenza LGPL / CC BY-SA 2.0), dai dati di
// spacy-lookups-data. Le classi di frequenza (COMUNI) vengono da wordfreq di Robyn Speer (dati CC BY-SA 4.0).
// Formato compatto ("front coding"): le parole sono in ordine alfabetico; ogni parola comincia con una lettera
// MAIUSCOLA che dice quante lettere ha in comune con quella prima (A = 0, B = 1, C = 2…), seguita dal resto.
// Si decodifica una volta sola, la prima volta che serve (vedi dizionario()).
const PAROLE = '';

// le parole più usate, in tre fasce: molto comuni, comuni, meno comuni (le altre sono rare). Servono al computer
// (conosce meglio le parole comuni) e per scegliere le parole degli anagrammi.
const COMUNI = [
  '',
  '',
  '',
];

function decodifica(s) {
  const out = [];
  let prec = '';
  let i = 0;
  while (i < s.length) {
    const k = s.charCodeAt(i) - 65;
    let j = i + 1;
    while (j < s.length && s.charCodeAt(j) >= 97) j++;
    prec = prec.slice(0, k) + s.slice(i + 1, j);
    out.push(prec);
    i = j;
  }
  return out;
}

let elenco = null;
let fasce = null;
// tutte le parole, in ordine alfabetico (per la ricerca binaria): quelle di Morph-it più le parole aggiunte
// (paroliere-aggiunte.js: parole comuni che mancavano, come "come", "quando", "perché", "aglio")
function dizionario() {
  if (!elenco) {
    const a = decodifica(PAROLE), b = decodifica(require('./paroliere-aggiunte'));
    elenco = [];
    let i = 0, j = 0;
    while (i < a.length || j < b.length) {
      const x = j >= b.length || (i < a.length && a[i] <= b[j]) ? a[i++] : b[j++];
      if (elenco[elenco.length - 1] !== x) elenco.push(x);
    }
  }
  return elenco;
}
// la prima posizione con una parola >= p
function posizione(p) {
  const e = dizionario();
  let a = 0, b = e.length;
  while (a < b) { const m = (a + b) >> 1; if (e[m] < p) a = m + 1; else b = m; }
  return a;
}
const esiste = (w) => { const e = dizionario(); const i = posizione(w); return i < e.length && e[i] === w; };
// c'è almeno una parola che comincia così?
const prefisso = (p) => { const e = dizionario(); const i = posizione(p); return i < e.length && e[i].startsWith(p); };
// fascia di frequenza: 3 = molto comune, 2 = comune, 1 = meno comune, 0 = rara
function fascia(w) {
  if (!fasce) {
    fasce = new Map();
    COMUNI.forEach((s, k) => { for (const x of decodifica(s)) fasce.set(x, 3 - k); });
  }
  return fasce.get(w) || 0;
}
const normalizza = (t) => String(t ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z]/g, '');

module.exports = { dizionario, esiste, prefisso, fascia, normalizza, decodifica, COMUNI };
